1	// Official entry point for evidence runs of the SignalScout pipelines.
2	//
3	//   npx tsx scripts/run-pipeline.ts --pipeline baseline
4	//   npx tsx scripts/run-pipeline.ts --pipeline baseline --llm real --confirm-spend
5	//
6	// Options: --pipeline baseline, --llm fake|real (default fake), --confirm-spend
7	// (required with --llm real), --label <string> (default: pipeline name),
8	// --config dev|eval (default eval).
9	//
10	// Writes runs/<timestamp>-<label>.json with counts, ids, costs, issue codes,
11	// tokens and timings only: no company records, keys or headers.
12	
13	import { mkdir, writeFile } from "node:fs/promises";
14	import { span } from "neatlogs";
15	import {
16	  FakeLlmClient,
17	  type LlmClient,
18	  type PipelineResult,
19	  runBaselinePipeline,
20	} from "../src/core/agent";
21	import { createGatewayLlmClient } from "../src/core/agent/gateway-client";
22	import { neatlogsTracer } from "../src/core/agent/neatlogs-tracer";
23	import { FixtureProvider } from "../src/core/data/fixture-provider";
24	import { closeTracing, initTracing } from "../src/core/observability/tracing";
25	import { DEFAULT_RUN_CONFIG, DEV_RUN_CONFIG, type RunConfig } from "../src/core/types";
26	
27	// What the evidence ICP means in words; matches describeIcp for the open ICP.
28	const EVIDENCE_ICP_DESCRIPTION = "Companies in any industry of any size in any location.";
29	
30	// Simulated at measured Crustdata prices (USD per record).
31	const SIMULATED_COST_PER_RECORD = { search: 0.069, enrich: 0.6 } as const;
32	
33	const EVAL_RUN_CONFIG: RunConfig = {
34	  ...DEFAULT_RUN_CONFIG,
35	  max_search_results: 10,
36	  max_enrichments: 5,
37	};
38	
39	// The ICP every evidence run uses, so runs are comparable. Open: no industry,
40	// size, location or keyword filter, so it matches every fixture.
41	const EVIDENCE_ICP = {
42	  industry: "",
43	  employee_count_ranges: [],
44	  locations: [],
45	  keywords: [],
46	  excluded_domains: [],
47	};
48	
49	interface Args {
50	  readonly pipeline: "baseline";
51	  readonly llm: "fake" | "real";
52	  readonly confirm_spend: boolean;
53	  readonly label: string;
54	  readonly config: "dev" | "eval";
55	}
56	
57	class UsageError extends Error {}
58	
59	function parseArgs(argv: readonly string[]): Args {
60	  let pipeline: string | undefined;
61	  let llm = "fake";
62	  let confirm_spend = false;
63	  let label: string | undefined;
64	  let config = "eval";
65	  const value = (i: number, flag: string): string => {
66	    const v = argv[i + 1];
67	    if (v === undefined || v.startsWith("--")) throw new UsageError(`${flag} needs a value.`);
68	    return v;
69	  };
70	  for (let i = 0; i < argv.length; i++) {
71	    const flag = argv[i];
72	    switch (flag) {
73	      case "--pipeline":
74	        pipeline = value(i++, flag);
75	        break;
76	      case "--llm":
77	        llm = value(i++, flag);
78	        break;
79	      case "--label":
80	        label = value(i++, flag);
81	        break;
82	      case "--config":
83	        config = value(i++, flag);
84	        break;
85	      case "--confirm-spend":
86	        confirm_spend = true;
87	        break;
88	      default:
89	        throw new UsageError(`Unknown argument: ${flag}`);
90	    }
91	  }
92	  if (pipeline === undefined) throw new UsageError("--pipeline is required (baseline).");
93	  if (pipeline !== "baseline") {
94	    throw new UsageError(
95	      `Unsupported pipeline "${pipeline}". Only "baseline" exists; the improved pipeline is not built yet.`,
96	    );
97	  }
98	  if (llm !== "fake" && llm !== "real") throw new UsageError(`--llm must be fake or real, got "${llm}".`);
99	  if (config !== "dev" && config !== "eval") {
100	    throw new UsageError(`--config must be dev or eval, got "${config}".`);
101	  }
102	  if (llm === "real" && !confirm_spend) {
103	    throw new UsageError("--llm real spends money on the model gateway. Add --confirm-spend to proceed.");
104	  }
105	  const finalLabel = label ?? pipeline;
106	  if (finalLabel.trim() === "") throw new UsageError("--label must not be empty.");
107	  return { pipeline, llm, confirm_spend, label: finalLabel, config };
108	}
109	
110	function buildLlm(kind: Args["llm"]): LlmClient {
111	  if (kind === "fake") return new FakeLlmClient();
112	  const apiKey = process.env.LITELLM_API_KEY;
113	  if (apiKey === undefined || apiKey.trim() === "") {
114	    throw new UsageError("LITELLM_API_KEY is not set; it is required for --llm real.");
115	  }
116	  return createGatewayLlmClient({ apiKey });
117	}
118	
119	// Fake-client token counts are made up; only real gateway usage is measured.
120	function tokenBasis(kind: Args["llm"]): "simulated" | "measured" {
121	  return kind === "fake" ? "simulated" : "measured";
122	}
123	
124	function fileSafe(label: string): string {
125	  return label.replace(/[^A-Za-z0-9._-]+/g, "-").replace(/^-+|-+$/g, "") || "run";
126	}
127	
128	function buildReport(args: Args, config: RunConfig, result: PipelineResult, started_at: string) {
129	  const { run, usage } = result;
130	  return {
131	    started_at,
132	    label: args.label,
133	    pipeline: args.pipeline,
134	    icp_description: EVIDENCE_ICP_DESCRIPTION,
135	    config_name: args.config,
136	    config,
137	    trace_id: run.trace_id,
138	    status: result.status,
139	    counts: run.counts,
140	    cost_usd_by_step: run.cost_usd_by_step,
141	    timings_ms_by_step: run.timings_ms_by_step,
142	    cost_basis: {
143	      provider: "simulated",
144	      provider_cost_per_record_usd: SIMULATED_COST_PER_RECORD,
145	      llm_calls_by_basis: usage.llm_cost.calls_by_basis,
146	    },
147	    provider_usage: usage.provider,
148	    llm: {
149	      mode: args.llm,
150	      token_basis: tokenBasis(args.llm),
151	      calls: usage.llm_calls,
152	      http_attempts: usage.llm_http_attempts,
153	      input_tokens: run.counts.llm_input_tokens,
154	      output_tokens: run.counts.llm_output_tokens,
155	      gateway_reported_usd: usage.llm_cost.gateway_reported_usd,
156	      estimated_usd: usage.llm_cost.estimated_usd,
157	      known_usd: usage.llm_cost.known_usd,
158	      cost_complete: usage.llm_cost.complete,
159	    },
160	    issue_codes: result.issues.map((i) => i.code),
161	    company_ids: result.prospects.map((p) => p.raw.crustdata_company_id),
162	    prospects: result.prospects.map((p) => ({
163	      company_id: p.raw.crustdata_company_id,
164	      enrichment: p.enrichment.status,
165	      assessment: p.assessment.status,
166	      llm_call_number: p.llm_call?.call_number ?? null,
167	    })),
168	  };
169	}
170	
171	async function main(): Promise<void> {
172	  const args = parseArgs(process.argv.slice(2));
173	  const config = args.config === "dev" ? DEV_RUN_CONFIG : EVAL_RUN_CONFIG;
174	
175	  const provider = new FixtureProvider({ config, cost_per_record: SIMULATED_COST_PER_RECORD });
176	  const llm = buildLlm(args.llm);
177	  const started_at = new Date().toISOString();
178	
179	  await initTracing({ run_label: args.label });
180	  let result: PipelineResult;
181	  try {
182	    const run = span({ kind: "WORKFLOW", name: "signalscout_run" }, () =>
183	      runBaselinePipeline(
184	        EVIDENCE_ICP,
185	        { provider, budget: provider.budget, llm, tracer: neatlogsTracer },
186	        { config },
187	      ),
188	    );
189	    result = await run();
190	  } finally {
191	    await closeTracing();
192	  }
193	
194	  const report = buildReport(args, config, result, started_at);
195	  await mkdir("runs", { recursive: true });
196	  const path = `runs/${started_at.replace(/[:.]/g, "-")}-${fileSafe(args.label)}.json`;
197	  await writeFile(path, `${JSON.stringify(report, null, 2)}\n`);
198	
199	  const { counts, cost_usd_by_step: cost } = result.run;
200	  const llmCost = result.usage.llm_cost;
201	  console.log(`run ${result.run.trace_id}  status=${result.status}  label=${args.label}`);
202	  console.log(
203	    `counts   searched=${counts.searched} enriched=${counts.enriched} delivered=${counts.delivered} llm_calls=${counts.llm_calls}`,
204	  );
205	  console.log(`tokens   in=${counts.llm_input_tokens} out=${counts.llm_output_tokens}  (${tokenBasis(args.llm)})`);
206	  console.log(
207	    `provider search=$${cost.search.toFixed(3)} enrich=$${cost.enrich.toFixed(3)}  (simulated at measured Crustdata prices)`,
208	  );
209	  console.log(
210	    `llm      gateway_reported=$${llmCost.gateway_reported_usd.toFixed(4)} (${llmCost.calls_by_basis.gateway_reported} calls)` +
211	      `  estimated=$${llmCost.estimated_usd.toFixed(4)} (${llmCost.calls_by_basis.estimated} calls)` +
212	      `  unavailable=${llmCost.calls_by_basis.unavailable} calls`,
213	  );
214	  console.log(`issues   ${result.issues.map((i) => i.code).join(", ") || "none"}`);
215	  console.log(`report   ${path}`);
216	  if (result.status === "stopped") {
217	    console.error("The run stopped early; see the issue codes above.");
218	    process.exitCode = 1;
219	  }
220	}
221	
222	main().catch((err) => {
223	  console.error(err instanceof UsageError ? err.message : `Run failed: ${err instanceof Error ? err.message : "unknown error"}`);
224	  process.exitCode = 1;
225	});
