1	// Naive baseline pipeline: plan -> search -> enrich -> assess. It deliberately
2	// skips validation, deduplication, buildFacts(), validateAssessment() and
3	// checkClaims(), so its trace shows what the unguarded agent does.
4	// No network of its own: data comes from the CompanyProvider and model output
5	// from the LlmClient passed in.
6	
7	import type { SearchFilters } from "../data/provider";
8	import { DEV_RUN_CONFIG, type RawCompany } from "../types";
9	import { buildAssessmentMessages, parseAssessment } from "./assess";
10	import { enrichInSearchOrder } from "./enrich";
11	import { assessmentCriteria, buildSearchFilters, describeIcp } from "./icp";
12	import type { LlmErrorCategory, LlmResponse } from "./llm";
13	import type { LlmCostBasis, LlmKeySpend } from "./llm-cost";
14	import { LLM_TEMPERATURE } from "./llm-policy";
15	import { RunRecorder } from "./recorder";
16	import { noopTracer, type TraceAttributes } from "./tracer";
17	import type {
18	  AssessmentOutcome,
19	  BaselineProspect,
20	  EnrichmentOutcome,
21	  IcpInput,
22	  LlmCallRecord,
23	  LlmCostSummary,
24	  PipelineDeps,
25	  PipelineIssue,
26	  PipelineOptions,
27	  PipelineResult,
28	  PipelineStatus,
29	} from "./types";
30	
31	// Span attributes for one model call, from the same record the result holds.
32	function callAttributes(call: LlmCallRecord): TraceAttributes {
33	  return {
34	    "llm.call_number": call.call_number,
35	    "llm.attempts": call.attempts,
36	    "llm.header_source": call.header_source,
37	    "llm.cost_basis": call.cost.basis,
38	    ...(call.cost.basis !== "unavailable" ? { "llm.cost_usd": call.cost.usd } : {}),
39	    ...(call.usage
40	      ? {
41	          "llm.prompt_tokens": call.usage.prompt_tokens,
42	          "llm.completion_tokens": call.usage.completion_tokens,
43	        }
44	      : {}),
45	    ...(call.key_spend?.spend_usd !== undefined
46	      ? { "llm.key_spend_usd": call.key_spend.spend_usd }
47	      : {}),
48	    ...(call.key_spend?.max_budget_usd !== undefined
49	      ? { "llm.key_max_budget_usd": call.key_spend.max_budget_usd }
50	      : {}),
51	  };
52	}
53	
54	type SearchOutcome =
55	  | { readonly kind: "found"; readonly companies: readonly RawCompany[] }
56	  | { readonly kind: "empty" }
57	  | { readonly kind: "stopped" };
58	
59	export async function runBaselinePipeline(
60	  icp: IcpInput,
61	  deps: PipelineDeps,
62	  options: PipelineOptions = {},
63	): Promise<PipelineResult> {
64	  const config = options.config ?? DEV_RUN_CONFIG;
65	  const assessScope = options.assess ?? "all_searched";
66	  const tracer = deps.tracer ?? noopTracer;
67	  const trace_id = deps.trace_id ?? crypto.randomUUID();
68	  const recorder = new RunRecorder(deps.now ?? Date.now);
69	  const input_description = describeIcp(icp);
70	  const issues: PipelineIssue[] = [];
71	  let llmHttpAttempts = 0;
72	  const llmCost: {
73	    gateway_reported_usd: number;
74	    estimated_usd: number;
75	    known_usd: number;
76	    calls_by_basis: Record<LlmCostBasis, number>;
77	    latest_key_spend?: LlmKeySpend;
78	  } = {
79	    gateway_reported_usd: 0,
80	    estimated_usd: 0,
81	    known_usd: 0,
82	    calls_by_basis: { gateway_reported: 0, estimated: 0, unavailable: 0 },
83	  };
84	
85	  return tracer.span(
86	    {
87	      name: "signalscout_baseline_run",
88	      kind: "WORKFLOW",
89	      input: { trace_id, icp },
90	      attributes: {
91	        "signalscout.trace_id": trace_id,
92	        "signalscout.pipeline": "naive_baseline",
93	        "signalscout.model": config.model,
94	        "signalscout.max_search_results": config.max_search_results,
95	        "signalscout.max_enrichments": config.max_enrichments,
96	        "signalscout.max_llm_calls_per_run": config.max_llm_calls_per_run,
97	        "signalscout.max_output_tokens_per_call": config.max_output_tokens_per_call,
98	      },
99	    },
100	    async (root) => {
101	      const finish = (
102	        status: PipelineStatus,
103	        filters: SearchFilters,
104	        prospects: readonly BaselineProspect[],
105	      ): PipelineResult => {
106	        recorder.counts.delivered = prospects.length;
107	        const run = recorder.build(trace_id, input_description, config);
108	        const provider = deps.budget.snapshot();
109	        const llm_cost: LlmCostSummary = {
110	          ...llmCost,
111	          calls_by_basis: { ...llmCost.calls_by_basis },
112	          complete: llmCost.calls_by_basis.unavailable === 0,
113	        };
114	        root.setAttributes({
115	          "signalscout.status": status,
116	          "signalscout.searched": run.counts.searched,
117	          "signalscout.enriched": run.counts.enriched,
118	          "signalscout.delivered": run.counts.delivered,
119	          "signalscout.llm_calls": run.counts.llm_calls,
120	          "signalscout.llm_http_attempts": llmHttpAttempts,
121	          "signalscout.provider_cost_usd": provider.cost_usd,
122	          "signalscout.llm_cost_known_usd": llm_cost.known_usd,
123	          "signalscout.llm_cost_complete": llm_cost.complete,
124	          "signalscout.issue_codes": issues.map((i) => i.code),
125	        });
126	        return {
127	          status,
128	          run,
129	          filters,
130	          prospects,
131	          issues,
132	          usage: {
133	            provider,
134	            max_search_results: config.max_search_results,
135	            max_enrichments: config.max_enrichments,
136	            llm_calls: run.counts.llm_calls,
137	            max_llm_calls_per_run: config.max_llm_calls_per_run,
138	            llm_http_attempts: llmHttpAttempts,
139	            llm_cost,
140	          },
141	        };
142	      };
143	
144	      // 1. Plan: ICP -> SearchFilters (free industry autocomplete).
145	      const plan = await recorder.time("plan", () =>
146	        tracer.span({ name: "plan", kind: "CHAIN", input: icp }, async (span) => {
147	          const result = await buildSearchFilters(icp, deps.provider);
148	          span.setAttributes({
149	            "search.industries": result.filters.industries,
150	            "search.country": result.filters.country,
151	            "search.employee_count_ranges": result.filters.employee_count_ranges,
152	          });
153	          return result;
154	        }),
155	      );
156	      recorder.addCost("plan", plan.cost_usd);
157	      issues.push(...plan.issues);
158	      const filters = plan.filters;
159	
160	      // 2. Search.
161	      const search = await recorder.time("search", () =>
162	        tracer.span(
163	          { name: "search", kind: "TOOL", input: filters },
164	          async (span): Promise<SearchOutcome> => {
165	            const limit = config.max_search_results - deps.budget.snapshot().searched;
166	            if (limit <= 0) {
167	              issues.push({
168	                step: "search",
169	                code: "search_budget_exhausted",
170	                message: "No search results left in this run's budget.",
171	              });
172	              span.setAttributes({ "provider.outcome": "budget_exhausted" });
173	              return { kind: "stopped" };
174	            }
175	            const result = await deps.provider.searchCompanies(filters, limit);
176	            if (result.ok) {
177	              recorder.addCost("search", result.cost_usd);
178	              recorder.counts.searched = result.data.length;
179	              span.setAttributes({
180	                "provider.outcome": "ok",
181	                "provider.limit": limit,
182	                "provider.returned": result.data.length,
183	                "provider.cost_usd": result.cost_usd,
184	                "provider.calls": result.calls,
185	              });
186	              return { kind: "found", companies: result.data };
187	            }
188	            const category = result.error.category;
189	            span.setAttributes({ "provider.outcome": category, "provider.limit": limit });
190	            if (category === "no_match") {
191	              issues.push({
192	                step: "search",
193	                code: "search_no_match",
194	                message: "No companies match the search filters.",
195	                error_category: category,
196	              });
197	              return { kind: "empty" };
198	            }
199	            issues.push({
200	              step: "search",
201	              code: category === "budget_cap_reached" ? "search_budget_exhausted" : "search_failed",
202	              message: `Search failed with ${category}: ${result.error.message}`,
203	              error_category: category,
204	            });
205	            return { kind: "stopped" };
206	          },
207	        ),
208	      );
209	      if (search.kind === "stopped") return finish("stopped", filters, []);
210	      if (search.kind === "empty") return finish("completed_empty", filters, []);
211	      const companies = search.companies;
212	
213	      // 3. Enrich in search order, within the remaining enrichment budget.
214	      const enrich = await recorder.time("enrich", () =>
215	        tracer.span(
216	          {
217	            name: "enrich",
218	            kind: "TOOL",
219	            input: { companies: companies.map((c) => c.crustdata_company_id) },
220	          },
221	          async (span) => {
222	            const remaining = config.max_enrichments - deps.budget.snapshot().enriched;
223	            const result = await enrichInSearchOrder(companies, deps.provider, remaining);
224	            const statusCount = (status: EnrichmentOutcome["status"]) =>
225	              result.outcomes.filter((o) => o.status === status).length;
226	            span.setAttributes({
227	              "enrich.remaining_before": Math.max(0, remaining),
228	              "enrich.requested": result.requested,
229	              "enrich.enriched": statusCount("enriched"),
230	              "enrich.not_returned": statusCount("not_returned"),
231	              "enrich.skipped_budget": statusCount("skipped_budget"),
232	              "enrich.skipped_no_linkedin": statusCount("skipped_no_linkedin"),
233	              "enrich.failed": statusCount("failed"),
234	              "provider.cost_usd": result.cost_usd,
235	            });
236	            return result;
237	          },
238	        ),
239	      );
240	      recorder.addCost("enrich", enrich.cost_usd);
241	      recorder.counts.enriched = enrich.enriched.size;
242	      issues.push(...enrich.issues);
243	
244	      const pending = companies.map((company, i) => ({
245	        raw: enrich.enriched.get(i) ?? company,
246	        enrichment: enrich.outcomes[i],
247	      }));
248	
249	      // 4. Assess, one company at a time, within the model-call cap.
250	      const criteria = assessmentCriteria(icp);
251	      const prospects = await recorder.time("assess", () =>
252	        tracer.span(
253	          { name: "assess", kind: "AGENT", input: { companies: pending.length, criteria } },
254	          async (span) => {
255	            const out: BaselineProspect[] = [];
256	            let capReached = false;
257	            let stoppedBy: LlmErrorCategory | undefined;
258	            // Sequential on purpose: no parallel model calls.
259	            for (const prospect of pending) {
260	              if (assessScope === "enriched_only" && prospect.enrichment.status !== "enriched") {
261	                out.push({ ...prospect, assessment: { status: "not_assessed", reason: "not_enriched" } });
262	                continue;
263	              }
264	              if (stoppedBy) {
265	                out.push({ ...prospect, assessment: { status: "not_assessed", reason: "llm_stopped" } });
266	                continue;
267	              }
268	              if (recorder.counts.llm_calls >= config.max_llm_calls_per_run) {
269	                capReached = true;
270	                out.push({ ...prospect, assessment: { status: "not_assessed", reason: "llm_call_cap" } });
271	                continue;
272	              }
273	              const { assessment, llm_call } = await assessOne(prospect);
274	              out.push({ ...prospect, assessment, llm_call });
275	              // Every later call would fail the same way, so stop spending attempts.
276	              if (
277	                assessment.status === "failed" &&
278	                (assessment.error_category === "auth_failed" ||
279	                  assessment.error_category === "rate_limited")
280	              ) {
281	                stoppedBy = assessment.error_category;
282	              }
283	            }
284	            if (stoppedBy) {
285	              issues.push({
286	                step: "assess",
287	                code: "llm_stopped",
288	                message: `Stopped assessing after a ${stoppedBy} model error.`,
289	                llm_error_category: stoppedBy,
290	              });
291	            }
292	            if (capReached) {
293	              issues.push({
294	                step: "assess",
295	                code: "llm_call_cap_reached",
296	                message: `Stopped assessing after ${config.max_llm_calls_per_run} model calls.`,
297	              });
298	            }
299	            if (llmCost.calls_by_basis.unavailable > 0) {
300	              issues.push({
301	                step: "assess",
302	                code: "llm_cost_incomplete",
303	                message: `Model cost is unavailable for ${llmCost.calls_by_basis.unavailable} call(s); the recorded assess cost is a lower bound.`,
304	              });
305	            }
306	            span.setAttributes({
307	              "llm.calls": recorder.counts.llm_calls,
308	              "llm.http_attempts": llmHttpAttempts,
309	              "llm.input_tokens": recorder.counts.llm_input_tokens,
310	              "llm.output_tokens": recorder.counts.llm_output_tokens,
311	              "llm.cost_known_usd": llmCost.known_usd,
312	              "llm.cost_complete": llmCost.calls_by_basis.unavailable === 0,
313	              "assess.assessed": out.filter((p) => p.assessment.status === "assessed").length,
314	              "assess.failed": out.filter((p) => p.assessment.status === "failed").length,
315	              "assess.not_assessed": out.filter((p) => p.assessment.status === "not_assessed").length,
316	            });
317	            return out;
318	          },
319	        ),
320	      );
321	
322	      return finish("completed", filters, prospects);
323	
324	      async function assessOne(
325	        prospect: Pick<BaselineProspect, "raw" | "enrichment">,
326	      ): Promise<{ assessment: AssessmentOutcome; llm_call: LlmCallRecord }> {
327	        const messages = buildAssessmentMessages(input_description, criteria, icp, prospect);
328	        // CHAIN, not LLM: a wrapOpenAI client records the LLM span itself, so
329	        // this span is the agent's step around it. The prompt and completion
330	        // are only captured here when the client does not record them.
331	        const recordsLlm = deps.llm.records_llm_spans;
332	        return tracer.span(
333	          {
334	            name: "assess_company",
335	            kind: "CHAIN",
336	            input: recordsLlm
337	              ? { company_id: prospect.raw.crustdata_company_id, enrichment_status: prospect.enrichment.status }
338	              : messages,
339	            attributes: {
340	              "company.id": prospect.raw.crustdata_company_id,
341	              "company.enrichment_status": prospect.enrichment.status,
342	              "llm.model": config.model,
343	              "llm.temperature": LLM_TEMPERATURE,
344	              "llm.max_output_tokens": config.max_output_tokens_per_call,
345	            },
346	          },
347	          async (span) => {
348	            recorder.counts.llm_calls += 1;
349	            const call_number = recorder.counts.llm_calls;
350	            let response: LlmResponse;
351	            try {
352	              response = await deps.llm.complete({
353	                model: config.model,
354	                messages,
355	                max_output_tokens: config.max_output_tokens_per_call,
356	                temperature: LLM_TEMPERATURE,
357	              });
358	            } catch (err) {
359	              // Clients should not throw; guard anyway so one company cannot end the run.
360	              response = {
361	                ok: false,
362	                error: {
363	                  category: "model_error",
364	                  message: err instanceof Error ? err.message : String(err),
365	                },
366	                meta: {
367	                  model: config.model,
368	                  attempts: 1,
369	                  retry_waits_ms: [],
370	                  cost: { basis: "unavailable" },
371	                  header_source: "none",
372	                },
373	              };
374	            }
375	
376	            const llm_call: LlmCallRecord = { ...response.meta, call_number };
377	            recordCall(llm_call);
378	            llm_call.retry_waits_ms.forEach((wait_ms, i) =>
379	              span.addEvent("llm_retry", { "llm.retry": i + 1, "llm.retry_wait_ms": wait_ms }),
380	            );
381	            span.setAttributes(callAttributes(llm_call));
382	
383	            if (!response.ok) {
384	              span.setAttributes({
385	                "assess.outcome": "llm_error",
386	                "llm.error_category": response.error.category,
387	              });
388	              return {
389	                llm_call,
390	                assessment: {
391	                  status: "failed",
392	                  reason: "llm_error",
393	                  message: response.error.message,
394	                  error_category: response.error.category,
395	                },
396	              };
397	            }
398	            span.setAttributes({ "llm.truncated": response.truncated });
399	            if (!recordsLlm) span.setAttributes({ "llm.output": response.text });
400	
401	            if (response.truncated) {
402	              span.setAttributes({ "assess.outcome": "truncated" });
403	              return {
404	                llm_call,
405	                assessment: {
406	                  status: "failed",
407	                  reason: "truncated",
408	                  message: `Model output hit the ${config.max_output_tokens_per_call}-token limit.`,
409	                },
410	              };
411	            }
412	            const parsed = parseAssessment(response.text);
413	            span.setAttributes({ "assess.outcome": parsed.ok ? "assessed" : "malformed_output" });
414	            return {
415	              llm_call,
416	              assessment: parsed.ok
417	                ? { status: "assessed", assessment: parsed.assessment }
418	                : { status: "failed", reason: "malformed_output", message: parsed.message },
419	            };
420	          },
421	        );
422	      }
423	
424	      function recordCall(call: LlmCallRecord): void {
425	        llmHttpAttempts += call.attempts;
426	        if (call.usage) {
427	          recorder.counts.llm_input_tokens += call.usage.prompt_tokens;
428	          recorder.counts.llm_output_tokens += call.usage.completion_tokens;
429	        }
430	        llmCost.calls_by_basis[call.cost.basis] += 1;
431	        if (call.cost.basis === "gateway_reported") {
432	          llmCost.gateway_reported_usd += call.cost.usd;
433	          recorder.addCost("assess", call.cost.usd);
434	        } else if (call.cost.basis === "estimated") {
435	          llmCost.estimated_usd += call.cost.usd;
436	          recorder.addCost("assess", call.cost.usd);
437	        }
438	        llmCost.known_usd = llmCost.gateway_reported_usd + llmCost.estimated_usd;
439	        if (call.key_spend) llmCost.latest_key_spend = call.key_spend;
440	      }
441	    },
442	  );
443	}
